INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE (r.name='superadmin' OR LOWER(r.name) IN ('hrd','personalia')) AND p.name IN ('hrd_assessments.view','hrd_assessments.manage','hrd_categories.view','hrd_categories.manage','hrd_rules.view','hrd_rules.manage');
